                        dur = mdia->mediaHeader->duration - (*samp)->DTS;
                } else {
                        stbl_GetSampleDTS(mdia->information->sampleTable->TimeToSample, sampleNumber+1, &dur);
                        dur -= (*samp)->DTS;
                }
                e = gf_isom_rewrite_text_sample(*samp, sdesc_idx, (u32) dur);
                if (e) return e;
